// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint256 newWinnersPerPeriodAmount) public {
        // 1. Restrict to reasonable domain (positive amount)
        vm.assume(newWinnersPerPeriodAmount > 0);

        // 2. make the caller an admin so the call succeeds
        vm.startPrank(address(this));
        c.adjustAdminAccess(address(this), true);
        c.updateWinnersPerPeriod(newWinnersPerPeriodAmount);
        vm.stopPrank();

        // 3. assert that winnersPerPeriod equals the passed amount
        assertEq(c.winnersPerPeriod(), newWinnersPerPeriodAmount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint256 newAmount) public {
        vm.assume(newAmount != 0);
        vm.prank(address(this));
        c.updateWinnersPerPeriod(newAmount);
        assertTrue(c.winnersPerPeriod() == newAmount);
    }
}

